package main

import (
	"crypto/rand"
	"errors"
	"sync"
	"time"
)

// Link представляет сокращённую ссылку и накопленную статистику переходов.
type Link struct {
	Code      string    `json:"code"`
	URL       string    `json:"url"`
	Hits      int64     `json:"hits"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// LinkStore — потокобезопасное in-memory хранилище ссылок.
// Все методы безопасны для конкурентного вызова: состояние
// защищается sync.RWMutex.
type LinkStore struct {
	mu    sync.RWMutex
	links map[string]*Link
}

// errCollision — ошибка, если после нескольких попыток не удалось
// сгенерировать уникальный code.
var errCollision = errors.New("не удалось сгенерировать уникальный code")

// NewLinkStore создаёт пустое хранилище ссылок.
func NewLinkStore() *LinkStore {
	return &LinkStore{links: make(map[string]*Link)}
}

const (
	codeAlphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	codeLength   = 6
	maxCodeTries = 32
)

// generateCode создаёт случайный code заданной длины из base62-алфавита.
func generateCode() (string, error) {
	b := make([]byte, codeLength)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	for i := range b {
		b[i] = codeAlphabet[int(b[i])%len(codeAlphabet)]
	}
	return string(b), nil
}

// Create сохраняет новую ссылку и возвращает её.
// Если совпадение code возникает, генерация повторяется.
func (s *LinkStore) Create(url string) (*Link, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for i := 0; i < maxCodeTries; i++ {
		code, err := generateCode()
		if err != nil {
			return nil, err
		}
		if _, exists := s.links[code]; exists {
			continue
		}
		now := time.Now().UTC()
		link := &Link{Code: code, URL: url, CreatedAt: now, UpdatedAt: now}
		s.links[code] = link
		return link, nil
	}
	return nil, errCollision
}

// Get возвращает ссылку по code. Второй результат показывает,
// найдена ли ссылка.
func (s *LinkStore) Get(code string) (*Link, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	link, ok := s.links[code]
	return link, ok
}

// RecordHit увеличивает счётчик переходов ссылки по code.
// Возвращает false, если ссылка не найдена.
func (s *LinkStore) RecordHit(code string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	link, ok := s.links[code]
	if !ok {
		return false
	}
	link.Hits++
	link.UpdatedAt = time.Now().UTC()
	return true
}

// Snapshot возвращает копию ссылки по code, чтобы вызывающий код
// мог читать состояние без блокировки хранилища.
func (s *LinkStore) Snapshot(code string) (Link, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	link, ok := s.links[code]
	if !ok {
		return Link{}, false
	}
	return *link, true
}

package main

import (
	"encoding/json"
	"errors"
	"net/http"
	"net/url"
	"strings"
)

// writeJSON пишет значение v в ответ в формате JSON с указанным кодом.
func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// writeErrorJSON пишет JSON-ошибку {"error": msg} с указанным кодом.
func writeErrorJSON(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

// createLinkHandler обрабатывает POST /api/links.
// Ожидает JSON-тело {"url": "https://..."} и возвращает 201
// с созданным code.
func createLinkHandler(store *LinkStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			w.Header().Set("Allow", http.MethodPost)
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var payload struct {
			URL string `json:"url"`
		}
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			writeErrorJSON(w, http.StatusBadRequest, "тело запроса не является корректным JSON")
			return
		}
		target := strings.TrimSpace(payload.URL)
		if target == "" {
			writeErrorJSON(w, http.StatusBadRequest, "поле url не указано")
			return
		}

		u, err := url.Parse(target)
		if err != nil || u.Host == "" || (u.Scheme != "http" && u.Scheme != "https") {
			writeErrorJSON(w, http.StatusBadRequest, "url должен быть абсолютной ссылкой http/https")
			return
		}

		link, err := store.Create(target)
		if err != nil {
			writeErrorJSON(w, http.StatusInternalServerError, "не удалось создать ссылку")
			return
		}

		writeJSON(w, http.StatusCreated, map[string]any{
			"code":      link.Code,
			"url":       link.URL,
			"short_url": r.URL.Scheme + "://" + r.Host + "/" + link.Code,
		})
	}
}

// redirectHandler обрабатывает GET /{code}: увеличивает счётчик
// переходов и возвращает 302 с заголовком Location.
func redirectHandler(store *LinkStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		code := r.PathValue("code")
		if code == "" {
			writeErrorJSON(w, http.StatusBadRequest, "code не указан")
			return
		}
		if !store.RecordHit(code) {
			writeErrorJSON(w, http.StatusNotFound, "ссылка не найдена")
			return
		}
		link, _ := store.Snapshot(code)
		http.Redirect(w, r, link.URL, http.StatusFound)
	}
}

// statsHandler обрабатывает GET /api/links/{code}/stats и возвращает
// статистику переходов в формате JSON.
func statsHandler(store *LinkStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		code := r.PathValue("code")
		link, ok := store.Snapshot(code)
		if !ok {
			writeErrorJSON(w, http.StatusNotFound, "ссылка не найдена")
			return
		}
		writeJSON(w, http.StatusOK, link)
	}
}

// validateTarget проверяет, что url — абсолютная ссылка http/https.
// Оставлен отдельной функцией для возможного повторного использования.
func validateTarget(raw string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return errors.New("некорректный url")
	}
	if u.Host == "" || (u.Scheme != "http" && u.Scheme != "https") {
		return errors.New("url должен быть абсолютной ссылкой http/https")
	}
	return nil
}

