func TestConcurrentRedirects(t *testing.T) {
	srv := newLinksTestServer()
	defer srv.Close()

	code := createTestLink(t, srv, "https://example.com")
	client := noRedirectClient()

	const workers = 32
	const perWorker = 8
	var wg sync.WaitGroup
	errCh := make(chan error, workers*perWorker)

	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < perWorker; j++ {
				resp, err := client.Get(srv.URL + "/" + code)
				if err != nil {
					errCh <- fmt.Errorf("GET /%s: %v", code, err)
					return
				}
				resp.Body.Close()
				if resp.StatusCode != http.StatusFound {
					errCh <- fmt.Errorf("code = %d, expected %d", resp.StatusCode, http.StatusFound)
					return
				}
			}
		}()
	}
	wg.Wait()
	close(errCh)
	for err := range errCh {
		t.Error(err)
	}

	expected := workers * perWorker
	if hits := getStats(t, srv, code); hits != expected {
		t.Errorf("hits = %d, expected %d", hits, expected)
	}
}
